args:
Write-Host 'QUIZ: sincronizacao automatica de todos os arquivos permitidos ativa.' -ForegroundColor Green
$ultimoFetch = [datetime]::MinValue
$ultimoAviso = ''
while ($true) {
  Start-Sleep -Seconds 10
  # Inclui arquivos novos e modificados em todas as pastas, inclusive .vscode.
  # Respeita .gitignore e NAO prepara arquivos excluidos para commit.
  $arquivos = @(git -c core.quotePath=false ls-files --cached --modified --others --exclude-standard)
  if ($LASTEXITCODE -ne 0) {
    if ($ultimoAviso -ne 'status') { Write-Host 'QUIZ: erro ao consultar arquivos.' -ForegroundColor Red; $ultimoAviso='status' }
    continue
  }
  $arquivosExistentes = @($arquivos | Where-Object { $_ -and (Test-Path -LiteralPath $_ -PathType Leaf) })
  # Evita publicar acidentalmente arquivos de credenciais mesmo se nao estiverem no .gitignore.
  $arquivosSeguros = @($arquivosExistentes | Where-Object { $_ -notmatch '(^|[/\\])\.env($|\.)|(^|[/\\])serviceAccount[^/\\]*\.json$|\.(pem|p12|pfx|key)$' })
  if ($arquivosSeguros.Count -gt 0) {
    git add -- $arquivosSeguros
    if ($LASTEXITCODE -ne 0) {
      if ($ultimoAviso -ne 'add') { Write-Host 'QUIZ: erro ao preparar arquivos.' -ForegroundColor Red; $ultimoAviso='add' }
      continue
    }
  }
  # Nao faz commit/push se houver exclusoes preparadas manualmente.
  $exclusoes = @(git diff --cached --name-only --diff-filter=D)
  if ($exclusoes.Count -gt 0) {
    if ($ultimoAviso -ne 'exclusao') { Write-Host 'QUIZ: exclusoes detectadas no indice. Publicacao pausada para revisao manual.' -ForegroundColor Yellow; $ultimoAviso='exclusao' }
    continue
  }
  git diff --cached --quiet
  if ($LASTEXITCODE -eq 1) {
    git -c gc.auto=0 commit -m 'Atualizacao automatica do sistema'
    if ($LASTEXITCODE -ne 0) {
      if ($ultimoAviso -ne 'commit') { Write-Host 'QUIZ: erro ao registrar alteracoes.' -ForegroundColor Red; $ultimoAviso='commit' }
      continue
    }
  }
  $agora = Get-Date
  if (($agora - $ultimoFetch).TotalSeconds -ge 60) {
    git -c gc.auto=0 -c fetch.writeCommitGraph=false fetch origin main --quiet
    if ($LASTEXITCODE -ne 0) {
      if ($ultimoAviso -ne 'fetch') { Write-Host 'QUIZ: sem acesso ao GitHub; nova tentativa em breve.' -ForegroundColor Yellow; $ultimoAviso='fetch' }
      continue
    }
    $ultimoFetch = $agora
  }
  git merge-base --is-ancestor origin/main HEAD
  if ($LASTEXITCODE -ne 0) {
    if ($ultimoAviso -ne 'divergencia') { Write-Host 'QUIZ: commits remotos pendentes. Publicacao pausada; integrar manualmente antes de enviar.' -ForegroundColor Yellow; $ultimoAviso='divergencia' }
    continue
  }
  $quantidade = [int](git rev-list --count origin/main..HEAD)
  if ($LASTEXITCODE -ne 0) { continue }
  if ($quantidade -gt 0) {
    git -c gc.auto=0 push origin main
    if ($LASTEXITCODE -eq 0) { Write-Host 'QUIZ: Publicacao concluida.' -ForegroundColor Green; $ultimoAviso='' }
    elseif ($ultimoAviso -ne 'push') { Write-Host 'QUIZ: envio nao concluido; nova tentativa em breve.' -ForegroundColor Yellow; $ultimoAviso='push' }
  } else { $ultimoAviso='' }
}
